    hubCanvas = canvases[k]; break;
  }
}
return JSON.stringify({
  frank_location: frankLoc,
  hour: v.game_state.time_state.current_hour,
  day: v.game_state.time_state.current_day,
  current_canvas: v.game_state.current_canvas,
  hub_found: !!hubCanvas,
  hub_id: hubCanvas ? hubCanvas.id : null,
  hub_priority: hubCanvas ? hubCanvas.priority : null,
  setup_keys: Object.keys(setupRef).slice(0, 30)
});

