var sc = SugarCube;
var setupRef = sc.setup;
var idMap = setupRef._canvasByIdMap || {};
var keys = Object.keys(idMap);
// Find any key whose canvas references frank kitchen morning
var found = [];
for (var i = 0; i < keys.length; i++) {
  var c = idMap[keys[i]];
  if (c && (c.id === 'frank_kitchen_morning_hub' || c.slug === 'frank_kitchen_morning_hub' || (c.name && c.name.indexOf('Kitchen — Frank, morning') >= 0))) {
    found.push({key: keys[i], id: c.id, slug: c.slug, name: c.name, npc: c.npc, location: c.location, trigger: c.trigger ? Object.keys(c.trigger) : null});
  }
}
return JSON.stringify({total_canvases: keys.length, sample_keys: keys.slice(0, 5), found_hub: found});

