var sc = SugarCube;
var setupRef = sc.setup;
// passage_to_location maps Canvas passage names to location UUIDs
var p2l = setupRef.passage_to_location || {};
var hubKey = 'Canvas_frank_kitchen_morning_hub_Node_1';
var hubLoc = p2l[hubKey];
// also check all 4 hubs
var hubs = ['Canvas_frank_kitchen_morning_hub_Node_1','Canvas_frank_kitchen_dinner_hub_Node_1','Canvas_frank_living_room_hub_Node_1','Canvas_frank_yard_hub_Node_1'];
var result = {};
for (var i = 0; i < hubs.length; i++) {
  result[hubs[i]] = p2l[hubs[i]] || 'NOT FOUND';
}
return JSON.stringify({hubs_passage_to_location: result, p2l_total: Object.keys(p2l).length, p2l_sample: Object.keys(p2l).slice(0, 5)});

var sc = SugarCube;
var setupRef = sc.setup;
// Find activity_make_tea UUID
var idMap = setupRef._canvasByIdMap || {};
var teaId = null;
for (var k in idMap) {
  if ((idMap[k].name || '').indexOf('Make tea') >= 0 || (idMap[k].displayName || '').indexOf('Make tea') >= 0 || (idMap[k].passageName || '').indexOf('make_tea') >= 0) {
    teaId = k; break;
  }
}
// Run 20 substitution checks to estimate hit rate
var hits = 0, misses = 0, results = [];
if (teaId && setupRef.checkAndSubstituteCanvas) {
  for (var i = 0; i < 20; i++) {
    var sub = setupRef.checkAndSubstituteCanvas(teaId);
    if (sub) { hits++; results.push({trial: i, sub: sub}); } else { misses++; }
  }
}
return JSON.stringify({tea_id: teaId, tea_name: teaId ? idMap[teaId].name : null, total_trials: 20, hits: hits, misses: misses, sample_hits: results.slice(0, 3)});

