var sc = SugarCube;
var setupRef = sc.setup;
var targetId = 'a62a2421-f7b1-4604-9b35-e76753cd99b4';
var target = setupRef.getCanvasById(targetId);
var valid = target ? setupRef.isCanvasValid(target) : 'no target';
var cond = {version:'1.0',logic:'AND',items:[{type:'trait',subject:'player',trait_key:'corruption',operator:'gte',value:5}]};
var condSat = setupRef.triggerConditionsSatisfied ? setupRef.triggerConditionsSatisfied(cond) : 'no fn';
return JSON.stringify({
  target_found: !!target,
  target_keys: target ? Object.keys(target) : null,
  target_substitution_only: target ? target.substitutionOnly : null,
  target_requiresNpc: target ? target.requiresNpc : null,
  is_valid: valid,
  condition_satisfied: condSat,
  player_corruption: sc.State.variables.player.core_traits.corruption
});

var sc = SugarCube;
var setupRef = sc.setup;
var idMap = setupRef._canvasByIdMap || {};
var subFound = [];
var subTargetIds = ['scene_frank_passes_kitchen_door','scene_frank_arrives_during_coffee','scene_frank_joins_porch','scene_frank_joins_couch','scene_frank_at_kitchen_sink_behind','scene_frank_at_open_bathroom_door','scene_frank_walks_in_shower'];
for (var k in idMap) {
  var c = idMap[k];
  for (var i = 0; i < subTargetIds.length; i++) {
    if ((c.passageName || '').indexOf(subTargetIds[i]) >= 0 || (c.name || '').toLowerCase().indexOf(subTargetIds[i].replace(/_/g,' ').toLowerCase()) >= 0) {
      subFound.push({slug: subTargetIds[i], uuid: k, passage: c.passageName, name: c.name, sub_only: c.substitutionOnly});
    }
  }
}
// Also check ALL canvasSubstitutions targets — do any resolve?
var subs = setupRef.canvasSubstitutions || {};
var subTargetsCheck = [];
for (var pk in subs) {
  for (var j = 0; j < subs[pk].length; j++) {
    var t = subs[pk][j].target_canvas_id;
    var tCanvas = setupRef.getCanvasById(t);
    subTargetsCheck.push({parent: pk, target: t, found: !!tCanvas});
  }
}
return JSON.stringify({total_canvases: Object.keys(idMap).length, sub_canvases_found: subFound, sub_target_checks: subTargetsCheck});

var sc = SugarCube;
