var sc = SugarCube;
var setupRef = sc.setup;
var lc = (setupRef.help_data || {}).locationCanvases || {};
var locKeys = Object.keys(lc);
// Look for any canvas with substitutionOnly=true across all location lists
var subOnlyFound = [];
for (var loc in lc) {
  var list = lc[loc] || [];
  for (var i = 0; i < list.length; i++) {
    if (list[i] && list[i].substitutionOnly === true) {
      subOnlyFound.push({loc: loc, id: list[i].id, name: list[i].name});
    }
  }
}
// Check if there's a separate sub_only registry
var helpKeys = Object.keys(setupRef.help_data || {});
return JSON.stringify({
  location_count: locKeys.length,
  sample_locations: locKeys.slice(0, 5),
  sub_only_in_location_canvases: subOnlyFound,
  help_data_keys: helpKeys
});

